/**
 * テスト用の楽天証券 CSV を作る。本物の取引データはコミットしない。
 *
 * 中身は作り物だが、**構造は本物と同じ**でなければ意味がない。ここで再現するのは
 * 解析器が実際に踏んだ落とし穴だけ：
 *
 *  1. 明細ヘッダに ［単位］ が4回出る（名前で索引を作ると潰れる）
 *  2. JP と US で 取引区分 / 口座区分 の列順が逆、US だけ [円換算] 列を持つ
 *  3. 振替出金 は金の定額積立（内部移動）であって取り崩しではない
 *  4. FLOW の全区分が最低1行ずつ出る（でないと未知区分の検出が動いていない）
 *  5. 金は g 単位・円建て、米株は 株 単位・USD 建て
 *  6. 同じ銘柄が同じ口座に2ロットある
 *  7. 純入金が負になる月がある
 *  8. 外貨建MMF の取得原価が極端に小さい（掛け目を推定した実装がここで壊れた）
 *
 * 合計段は行から**計算して**出す。二度打ちした数字を突き合わせても検算にならない。
 * 明細と合計段の 6 円差だけは意図的に残してある —— 本物の米株行の丸めがそうなっていて、
 * それを説明するテストが1本あるため。
 *
 * 使い方: node tests/fixtures/make-rakuten.mjs
 * 出力は UTF-8。CP932 への変換は同ディレクトリの手順どおり iconv で行う。
 */

import { writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const DIR = fileURLToPath(new URL('./rakuten/', import.meta.url))
const U = '［単位］'
const yen = (n) => Math.round(n).toLocaleString('en-US')
const signed = (n) => (n >= 0 ? `+${yen(n)}` : yen(n))
const q = (row) => row.map((v) => `"${v}"`).join(',')
const jpDate = (iso) => {
  const [y, m, d] = iso.split('-').map(Number)
  return `${y}/${m}/${d}`
}

/* ── 保有商品 ───────────────────────────────────────── */

// [種別, コード, 銘柄, 口座, 数量, 数量単位, 現在値, 価格単位, 時価[円], 時価[外貨], 評価損益[円]]
const POSITIONS = [
  ['国内株式', '7203', 'トヨタ自動車', '特定', '100', '株', '2,850.0', '円', 285_000, '-', 35_000],
  ['国内株式', '9432', '日本電信電話', 'NISA成長投資枠', '200', '株', '155.0', '円', 31_000, '-', -4_000],
  ['米国株式', 'AAPL', 'アップル', 'NISA成長投資枠', '2', '株', '300.0000', 'USD', 96_000, '600.00 USD', 21_000],
  ['米国株式', 'MSFT', 'マイクロソフト', '特定', '1', '株', '487.5000', 'USD', 78_000, '487.50 USD', 12_000],
  ['米国株式', 'MSFT', 'マイクロソフト', 'NISA成長投資枠', '3', '株', '487.5000', 'USD', 234_000, '1,462.50 USD', 40_000],
  ['投資信託', '', 'eMAXIS Slim 全世界株式(オール・カントリー)(オルカン)', 'NISAつみたて投資枠',
    '476,300', '口', '38,842', '円', 1_850_000, '-', 420_000],
  ['投資信託', '', 'eMAXIS Slim 全世界株式(オール・カントリー)(オルカン)', 'NISA成長投資枠',
    '252,300', '口', '38,842', '円', 980_000, '-', 280_000],
  // 同じファンドが同じ枠に2ロット。銘柄＋口座の組は一意ではない。
  ['投資信託', '', 'eMAXIS Slim 米国株式(S&P500)', 'NISA成長投資枠',
    '273,450', '口', '45,344', '円', 1_240_000, '-', 330_000],
  ['投資信託', '', 'eMAXIS Slim 米国株式(S&P500)', 'NISA成長投資枠',
    '134,530', '口', '45,344', '円', 610_000, '-', 95_000],
  // 取得原価が 5,199 円しかない。掛け目を推定する実装はここで桁を間違える。
  ['外貨建MMF', '', 'ノーザン・トラスト・米ドル・リクイディティ・ファンド(楽天・米ドルMMF)', '特定',
    '3,275', '口', '160.06', '円/USD', 5_240, '32.75 USD', 41],
  ['金・プラチナ', '-', '金', '-', '40.51230', 'g', '23,452', '円', 950_000, '-', 240_000],
]

const sum = (f) => POSITIONS.reduce((a, p) => a + f(p), 0)
const mv = (p) => p[8]
const gain = (p) => p[10]

const CASH = { 預り金: 5_120, 信用保証金: 900 }
const cashTotal = CASH['預り金'] + CASH['信用保証金']

// 明細の合計と合計段は 6 円ずれる（米株行の丸め）。本物がそうなっている。
const ROUNDING = 6
const holdingsStated = sum(mv) + ROUNDING
const grandTotal = holdingsStated + cashTotal

const byKind = {}
for (const p of POSITIONS) byKind[p[0]] = (byKind[p[0]] ?? 0) + mv(p)

function snapshotCsv() {
  const L = []
  const pad = (row, n = 12) => [...row, ...Array(Math.max(0, n - row.length)).fill('')]

  L.push(q(['■資産合計欄']))
  L.push(q(['', '時価評価額[円]', '前日比[円]', '前日比[％]', '前月比[円]', '前月比[％]',
    '評価損益[円]', '評価損益[％]', '', '実現損益[円]', '配当・分配金[円貨]', '配当・分配金[外貨]']))
  L.push(q(['資産合計', yen(grandTotal), '+12,340', '+0.19', '+210,500', '+3.42',
    signed(sum(gain)), '-', '', '+118,200', '3,240', '61.40']))
  L.push('')
  L.push(q(pad(['保有商品の評価額合計', yen(holdingsStated), '+12,340', '+0.19', '+210,500', '+3.42',
    signed(sum(gain)), '-', '', '', '', ''])))
  // 合計段は明細より 6 円多い（米株行）。他の種別は明細と一致する。
  const stated = { ...byKind, 米国株式: byKind['米国株式'] + ROUNDING }
  for (const kind of ['国内株式', '米国株式', '中国株式', '投資信託', '外貨建MMF', '国内債券', '外国債券', '金・プラチナ']) {
    const v = stated[kind] ?? 0
    const g = POSITIONS.filter((p) => p[0] === kind).reduce((a, p) => a + gain(p), 0)
    L.push(q(pad([kind, yen(v), '0', '0.00', '0', '0.00', v === 0 ? '0' : signed(g), '-', '', '-', '0', ''])))
  }
  L.push('')
  L.push(q(pad(['預り金合計', yen(cashTotal), '0', '0.00', '0', '0.00', '-', '-', '', '', '', ''])))
  for (const [k, v] of Object.entries(CASH)) {
    L.push(q(pad([k, yen(v), '0', '0.00', '0', '0.00', '-', '-', '', '', '', ''])))
  }
  L.push('')
  L.push(q(['楽天銀行普通預金残高', '未取得']))
  L.push('')
  L.push('')
  L.push(q(['■ 保有商品詳細 (すべて）']))
  L.push('')
  // ［単位］ が4回。名前で索引を作ると数量と価格の単位が同じ列に潰れる。
  L.push(q(['種別', '銘柄コード・ティッカー', '銘柄', '口座', '保有数量', U, '平均取得価額', U,
    '現在値', U, '現在値(更新日)', '(参考為替)', '前日比', U,
    '時価評価額[円]', '時価評価額[外貨]', '評価損益[円]', '評価損益[％]']))
  for (const p of POSITIONS) {
    const [kind, code, name, account, qty, qtyUnit, price, priceUnit, value, valueFx, g] = p
    const cost = value - g
    L.push(q([kind, code, name, account, qty, qtyUnit, yen(cost / 1000), priceUnit === 'USD' ? 'USD' : '円',
      price, priceUnit, '', '', '+1.0', priceUnit === 'USD' ? 'USD' : '円',
      yen(value), valueFx, signed(g), (g === 0 ? 0 : (g / cost) * 100).toFixed(2)]))
  }
  L.push('')
  L.push('')
  L.push(q(['■参考為替レート']))
  L.push('')
  L.push(q(['米ドル', '160.06', '円/USD', '(08/29  05:59)']))
  L.push(q(['ユーロ', '185.44', '円/EUR', '(08/29  06:49)']))
  return L.join('\n') + '\n'
}

