const cell = (v) => (typeof v === 'number' ? yen(v) : v)
const sortRows = (rows) => rows.sort((a, b) => b.settledOn.localeCompare(a.settledOn))

function jpCsv() {
  const head = ['受渡日', '約定日', '取引区分', '口座区分', '対象証券名', `単価［円/％］`,
    `数量［株/口/額面］`, '受渡金額（受取）', '受渡金額（支払）',
    `預り金（MRF）［円］`, `信用取引保証金［円］`, `米株信用取引保証金［円］`]
  const rows = sortRows(jp).map((t) => q([jpDate(t.settledOn), jpDate(t.tradedOn), t.type, t.account,
    t.security, t.unitPrice, t.qty, cell(t.received), cell(t.paid), '5,120', '900', '0']))
  return [head.join(','), ...rows].join('\n') + '\n'
}

function usCsv() {
  // JP と 3・4 列目が逆。位置を流用すると取引区分に「特定」が入る。
  const head = ['受渡日', '約定日', '口座区分', '取引区分', '対象証券名', '決済通貨', '単価',
    `数量［株 /口］`, '受渡金額（受取）', '受渡金額（受取）[円換算]',
    '受渡金額（支払）', '受渡金額（支払）[円換算]', '為替レート', '預り金',
    `米株信用取引保証金［米ドル］`]
  const rows = sortRows(us).map((t) => {
    const fx = 160.06
    const recFx = typeof t.received === 'number' ? (t.received / fx).toFixed(2) : '-'
    const paidFx = typeof t.paid === 'number' ? (t.paid / fx).toFixed(2) : '-'
    return q([jpDate(t.settledOn), jpDate(t.tradedOn), t.account, t.type, t.security, '米ドル',
      t.unitPrice, t.qty, recFx, cell(t.received), paidFx, cell(t.paid), '160.06', '0.00', '0.00'])
  })
  return [head.join(','), ...rows].join('\n') + '\n'
}

