/* ── 期待値を出力する。テストに書く数字はここから写す ─────── */
const netOf = (rows) => rows.reduce((a, t) => {
  const inflow = ['リアルタイム入金(ゆうちょ銀行)', 'らくらく入金(楽天銀行)', '入金(クレジットカード決済ご利用分)',
    '入金(楽天ペイ残高ご利用分)', '入金(楽天ポイント交換)', '入金(楽天ペイ残高注文エラー分)'].includes(t.type)
  const outflow = ['通常出金(ゆうちょ銀行)', '譲渡益税（所得税）', '譲渡益税（住民税）'].includes(t.type)
  return a + (inflow ? t.received : outflow ? -t.paid : 0)
}, 0)

const monthly = new Map()
for (const t of jp) {
  const n = netOf([t])
  if (n === 0) continue
  const k = t.settledOn.slice(0, 7)
  monthly.set(k, (monthly.get(k) ?? 0) + n)
}
const sorted = [...monthly].sort(([a], [b]) => a.localeCompare(b))
const last6 = sorted.slice(-6).map(([, v]) => v)
const mean = last6.reduce((a, b) => a + b, 0) / 6
const med = [...last6].sort((a, b) => a - b)
const nisa = POSITIONS.filter((p) => p[3].startsWith('NISA'))

